package com.campusnova.service;
import com.campusnova.config.CollegeProfile; import com.campusnova.dto.ChatRequest; import com.campusnova.knowledge.*; import com.campusnova.repository.ChatHistoryRepository; import org.junit.jupiter.api.*; import org.junit.jupiter.api.extension.ExtendWith; import org.mockito.*; import org.mockito.junit.jupiter.*; import org.mockito.quality.Strictness; import java.util.*; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.ArgumentMatchers.*; import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class) @MockitoSettings(strictness=Strictness.LENIENT) class NovaChatServiceTest { @Mock ConversationService conversation; @Mock KnowledgeRetrievalService retrieval; @Mock CollegeRelevanceService relevance; @Mock BedrockService bedrock; @Mock GroundingValidationService grounding; @Mock ChatHistoryRepository history; @Mock CollegeProfile profile; @InjectMocks NovaChatService nova; private ChatRequest request(String q){ChatRequest r=new ChatRequest();r.setQuestion(q);r.setSessionId("test-session");return r;} private RetrievalResult official(double score,String category){return new RetrievalResult(Collections.singletonList(new KnowledgeDocument("LBSCEK "+category,""+category,"Library information\nOfficial "+category+" information.",true,true,"https://lbscek.ac.in/"+category.toLowerCase()+"/")),score);} @BeforeEach void profile(){when(profile.getOfficialName()).thenReturn("L B S College of Engineering");when(profile.getOfficialDomain()).thenReturn("https://lbscek.ac.in/");}
 @Test void libraryQuestionUsesOnlyOfficialLibrarySource(){when(conversation.recentTerms(anyString())).thenReturn(Collections.emptyList());when(retrieval.retrieve(anyString(),anyCollection())).thenReturn(official(.9,"Library"));when(relevance.isCollegeRelated(anyString(),any(),anyCollection())).thenReturn(true);Map<String,Object> answer=nova.respond(request("When can I use the library?"));assertEquals("VERIFIED_OFFICIAL",answer.get("responseType"));assertTrue(answer.get("sources").toString().contains("Library"));}
 @Test void aiResponseRequiresOfficialContext(){when(conversation.recentTerms(anyString())).thenReturn(Collections.emptyList());when(retrieval.retrieve(anyString(),anyCollection())).thenReturn(official(.3,"Library"));when(relevance.isCollegeRelated(anyString(),any(),anyCollection())).thenReturn(true);when(bedrock.generate(anyString(),any())).thenReturn(Optional.of("Official library answer"));when(grounding.acceptable(anyString(),any())).thenReturn(true);assertEquals("AI_GROUNDED",nova.respond(request("Is the library open after class?")).get("responseType"));}
 @Test void lostIdWithNoOfficialSourceIsGeneralGuidanceWithoutCitations(){when(conversation.recentTerms(anyString())).thenReturn(Collections.emptyList());when(retrieval.retrieve(anyString(),anyCollection())).thenReturn(new RetrievalResult(Collections.emptyList(),0));when(relevance.isCollegeRelated(anyString(),any(),anyCollection())).thenReturn(true);Map<String,Object> answer=nova.respond(request("What should I do if I lose my college ID card?"));assertEquals("GENERAL_GUIDANCE",answer.get("responseType"));assertTrue(((List<?>)answer.get("sources")).isEmpty());}
 @Test void unrelatedQuestionStaysOutOfScope(){when(conversation.recentTerms(anyString())).thenReturn(Collections.emptyList());when(retrieval.retrieve(anyString(),anyCollection())).thenReturn(new RetrievalResult(Collections.emptyList(),0));when(relevance.isCollegeRelated(anyString(),any(),anyCollection())).thenReturn(false);assertEquals("OUT_OF_SCOPE",nova.respond(request("Give me a cooking recipe")).get("responseType"));}
 @Test void bedrockFailureFallsBackToRelevantOfficialSource(){when(conversation.recentTerms(anyString())).thenReturn(Collections.singletonList("library timings"));when(retrieval.retrieve(anyString(),anyCollection())).thenReturn(official(.3,"Library"));when(relevance.isCollegeRelated(anyString(),any(),anyCollection())).thenReturn(true);when(bedrock.generate(anyString(),any())).thenReturn(Optional.empty());assertEquals("VERIFIED_OFFICIAL",nova.respond(request("Is it open on Saturday?")).get("responseType"));verify(history).save(any());}}
